# -*- coding: utf-8 -*-
import socket
import string
import random
from contextlib import closing


class PeriodicProbeSender(object):
    def __init__(self, broadcast_address, timer, probing_period=0.25):
        self._probing_period = probing_period
        self._broadcast_address = broadcast_address
        self._timer = timer
        self._packet_contents = self._generate_random_string(length=16)

    def send_periodically(self):
        if not self._timer.is_started() or self._timer.is_timeout():
            self._send()
            self._timer.start(self._probing_period)

    @property
    def time_to_next_probe(self):
        return self._timer.remaining_time

    @property
    def packet_contents(self):
        return self._packet_contents

    def _send(self):
        with closing(socket.socket(socket.AF_INET, socket.SOCK_DGRAM)) as s:
            s.setsockopt(socket.SOL_SOCKET, socket.SO_BROADCAST, 1)
            s.sendto(self.packet_contents, self._broadcast_address)

    @staticmethod
    def _generate_random_string(length):
        return ''.join(random.choice(string.printable) for i in range(length)).encode()
